function y=fitness(a,b) 
n=size(a,1); 
for i=1:n 
 if a(i)==0 && b(i)==0 
 t(i)=0; 
 continue; 
 end 
 t(i)=a(i)+b(i)-40; 
 t(i)=t(i)*t(i); 
end 
y=sum(t); 
end 

